mapper.select:
SELECT * FROM `payment_reconciliation_issue`
WHERE issue_status = 'OPEN'
  AND (
    (#{paymentNo} IS NOT NULL AND payment_no = #{paymentNo})
    OR biz_order_no = #{bizOrderNo}
  )

SELECT id, issue_key AS issueKey, biz_type AS bizType, payment_no AS paymentNo, biz_order_no AS bizOrderNo, user_id AS userId, channel, issue_type AS issueType, issue_level AS issueLevel, issue_status AS issueStatus, issue_message AS issueMessage, payment_order_status AS paymentOrderStatus, voucher_order_status AS voucherOrderStatus, voucher_payment_status AS voucherPaymentStatus, payment_amount AS paymentAmount, recorded_refunded_amount AS recordedRefundedAmount, actual_refunded_amount AS actualRefundedAmount, last_checked_time AS lastCheckedTime, resolved_time AS resolvedTime, resolved_by AS resolvedBy, resolve_note AS resolveNote, create_time AS createTime, update_time AS updateTime FROM `payment_reconciliation_issue`
AND issue_status = #{status}
AND issue_type = #{issueType}
ORDER BY CASE WHEN issue_status = 'OPEN' THEN 0 ELSE 1 END, last_checked_time DESC, id DESC
